#!/usr/bin/env node
// Writes sdk/abi.ts (ABIs) and sdk/bytecode.json (deployable bytecode) from Foundry artifacts.
// Run after `forge build`. The generated files are committed so the SDK typechecks without a build.
import { readFile, writeFile } from 'node:fs/promises';
import { createHash } from 'node:crypto';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const contracts = ['TapeoutMinerPool', 'TapeoutEntitlementReceipt', 'TapeoutReceiptDistributor'];
const mocks = ['MockBEM', 'MockMining', 'MockNFT'];

async function artifact(source, name) {
  return JSON.parse(await readFile(path.join(root, 'out', `${source}.sol`, `${name}.json`), 'utf8'));
}

let abiSource = '// Generated by scripts/export-abi.mjs from Foundry artifacts. Do not edit.\n';
const bytecode = {};
for (const name of contracts) {
  const a = await artifact(name, name);
  abiSource += `export const ${name[0].toLowerCase()}${name.slice(1)}Abi = ${JSON.stringify(a.abi, null, 2)} as const;\n\n`;
  bytecode[name] = { bytecode: a.bytecode.object, sha256: createHash('sha256').update(Buffer.from(a.bytecode.object.slice(2), 'hex')).digest('hex') };
}
for (const name of mocks) {
  const a = await artifact('Mocks', name);
  abiSource += `export const ${name[0].toLowerCase()}${name.slice(1)}Abi = ${JSON.stringify(a.abi)} as const;\n\n`;
  bytecode[name] = { bytecode: a.bytecode.object, sha256: createHash('sha256').update(Buffer.from(a.bytecode.object.slice(2), 'hex')).digest('hex'), localTestOnly: true };
}
await writeFile(path.join(root, 'sdk', 'abi.ts'), abiSource);
await writeFile(path.join(root, 'sdk', 'bytecode.json'), JSON.stringify(bytecode, null, 2) + '\n');
console.log(JSON.stringify({ status: 'EXPORTED', contracts: [...contracts, ...mocks] }));
